using System;using System.Data;using System.Windows.Forms;using QuanLyBanDienThoai.BUS;
namespace QuanLyBanDienThoai.GUI {public class FormPhieuNhap:Form {readonly PhieuNhapHangBUS bus=new PhieuNhapHangBUS();readonly DataGridView master=new DataGridView(),detail=new DataGridView();public FormPhieuNhap(){Text="Danh sách phiếu nhập và chi tiết";Width=1000;Height=700;var refresh=new Button{Text="Làm mới",Dock=DockStyle.Top,Height=36};refresh.Click+=(s,e)=>LoadData();var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=300};master.Dock=DockStyle.Fill;detail.Dock=DockStyle.Fill;master.ReadOnly=detail.ReadOnly=true;master.SelectionMode=DataGridViewSelectionMode.FullRowSelect;split.Panel1.Controls.Add(master);split.Panel2.Controls.Add(detail);Controls.Add(split);Controls.Add(refresh);master.SelectionChanged+=(s,e)=>{try{if(master.CurrentRow?.DataBoundItem is DataRowView row)detail.DataSource=bus.GetChiTiet(Convert.ToInt32(row["MaPN"]));}catch(Exception ex){MessageBox.Show(ex.Message);}};LoadData();}void LoadData(){try{master.DataSource=bus.GetAll();}catch(Exception ex){MessageBox.Show(ex.Message);}}} }